using Microsoft.Data.Sqlite;
using System.Security.Claims;

public static class InventoryEndpoints
{
    static bool Manager(ClaimsPrincipal u)=>new[]{"owner","manager"}.Contains(u.FindFirstValue(ClaimTypes.Role)??"");
    static string UserId(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.NameIdentifier)!;
    static IResult Denied()=>Results.Json(new{error="Chỉ chủ quán hoặc quản lý được dùng kho."},statusCode:403);

    public static void MapInventoryEndpoints(this WebApplication app)
    {
        app.MapGet("/api/inventory/ingredients",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT i.*,CASE WHEN Quantity<=ReorderLevel THEN 1 ELSE 0 END LowStock,COALESCE((SELECT GROUP_CONCAT(p.Name,', ') FROM RecipeComponents r JOIN Products p ON p.Id=r.ProductId WHERE r.IngredientId=i.Id),'') AffectedProducts FROM Ingredients i WHERE IsActive=1 ORDER BY LowStock DESC,Name");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),code=r.S("Code"),name=r.S("Name"),category=r.S("Category"),unit=r.S("Unit"),quantity=Convert.ToDecimal(r["Quantity"]),reorderLevel=Convert.ToDecimal(r["ReorderLevel"]),averageCost=Convert.ToDecimal(r["AverageCost"]),lowStock=r.B("LowStock"),affectedProducts=r.S("AffectedProducts")}));});
        app.MapPost("/api/inventory/ingredients",async(IngredientDemoInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Name)||string.IsNullOrWhiteSpace(x.Unit)||x.ReorderLevel<0)return Results.BadRequest(new{error="Thông tin nguyên liệu không hợp lệ."});await using var c=DemoDb.Open();var id=DemoDb.Id();try{await DemoDb.Exec(c,"INSERT INTO Ingredients(Id,StoreId,Code,Name,Category,Unit,ReorderLevel,CreatedAt)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),NULLIF(@code,''),@name,NULLIF(@cat,''),@unit,@level,@now)",( "@id",id),("@code",x.Code?.Trim()??""),("@name",x.Name.Trim()),("@cat",x.Category?.Trim()??""),("@unit",x.Unit.Trim()),("@level",x.ReorderLevel),("@now",DemoDb.Now));return Results.Ok(new{id=Guid.Parse(id)});}catch(SqliteException){return Results.Conflict(new{error="Mã nguyên liệu đã tồn tại."});}});
        app.MapGet("/api/inventory/suppliers",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT * FROM Suppliers WHERE IsActive=1 ORDER BY Name");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),name=r.S("Name"),phone=r.S("Phone"),address=r.S("Address"),note=r.S("Note")}));});
        app.MapPost("/api/inventory/suppliers",async(SupplierDemoInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Tên nhà cung cấp không được trống."});await using var c=DemoDb.Open();var id=DemoDb.Id();await DemoDb.Exec(c,"INSERT INTO Suppliers(Id,StoreId,Name,Phone,Address,Note,CreatedAt)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@n,@p,@a,@note,@now)",( "@id",id),("@n",x.Name.Trim()),("@p",x.Phone?.Trim()),("@a",x.Address?.Trim()),("@note",x.Note?.Trim()),("@now",DemoDb.Now));return Results.Ok(new{id=Guid.Parse(id)});});
        app.MapGet("/api/inventory/receipts",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT r.*,COALESCE(s.Name,'Không chọn NCC') Supplier,(SELECT COUNT(*) FROM StockReceiptItems WHERE ReceiptId=r.Id) ItemCount FROM StockReceipts r LEFT JOIN Suppliers s ON s.Id=r.SupplierId ORDER BY r.CreatedAt DESC LIMIT 100");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),receiptNumber=r.L("ReceiptNumber"),status=r.S("Status"),totalCost=Convert.ToDecimal(r["TotalCost"]),createdAt=r.D("CreatedAt"),confirmedAt=r.DN("ConfirmedAt"),supplier=r.S("Supplier"),itemCount=r.I("ItemCount")}));});
        app.MapPost("/api/inventory/receipts",async(ReceiptDemoInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.Items.Count==0||x.Items.Any(i=>i.Quantity<=0||i.UnitCost<0))return Results.BadRequest(new{error="Phiếu nhập không hợp lệ."});await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var id=DemoDb.Id();var number=await ScalarLong(c,tx,"SELECT COALESCE(MAX(ReceiptNumber),999)+1 FROM StockReceipts");var total=x.Items.Sum(i=>i.Quantity*i.UnitCost);await DemoDb.Exec(c,tx,"INSERT INTO StockReceipts(Id,StoreId,ReceiptNumber,SupplierId,Note,TotalCost,CreatedBy,CreatedAt)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@no,@supplier,@note,@total,@u,@now)",( "@id",id),("@no",number),("@supplier",x.SupplierId),("@note",x.Note),("@total",total),("@u",UserId(u)),("@now",DemoDb.Now));foreach(var i in x.Items)await DemoDb.Exec(c,tx,"INSERT INTO StockReceiptItems(Id,ReceiptId,IngredientId,Quantity,UnitCost)VALUES(@id,@r,@i,@q,@cost)",( "@id",DemoDb.Id()),("@r",id),("@i",i.IngredientId),("@q",i.Quantity),("@cost",i.UnitCost));tx.Commit();return Results.Ok(new{id=Guid.Parse(id),receiptNumber=number,status="draft",totalCost=total});});
        app.MapPost("/api/inventory/receipts/{id:guid}/confirm",async(Guid id,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=DemoDb.Open();using var tx=c.BeginTransaction();if(await DemoDb.Exec(c,tx,"UPDATE StockReceipts SET Status='confirmed',ConfirmedBy=@u,ConfirmedAt=@now WHERE Id=@id AND Status='draft'",("@u",UserId(u)),("@now",DemoDb.Now),("@id",id))==0){tx.Rollback();return Results.Conflict(new{error="Phiếu không tồn tại hoặc đã xác nhận."});}var items=await DemoDb.Rows(c,tx,"SELECT * FROM StockReceiptItems WHERE ReceiptId=@id",("@id",id));foreach(var i in items){var old=(await DemoDb.Rows(c,tx,"SELECT Quantity,AverageCost FROM Ingredients WHERE Id=@id",("@id",i.S("IngredientId")))).First();var oq=Convert.ToDecimal(old["Quantity"]);var oc=Convert.ToDecimal(old["AverageCost"]);var qty=Convert.ToDecimal(i["Quantity"]);var cost=Convert.ToDecimal(i["UnitCost"]);var balance=oq+qty;var average=balance==0?oc:(oq*oc+qty*cost)/balance;await DemoDb.Exec(c,tx,"UPDATE Ingredients SET Quantity=@b,AverageCost=@avg WHERE Id=@id;INSERT INTO StockMovements(Id,IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,UnitCost,BalanceAfter,CreatedAt)VALUES(@mid,@id,@q,'Nhập kho',@u,'receipt','stock_receipt',@r,@cost,@b,@now)",( "@b",balance),("@avg",average),("@id",i.S("IngredientId")),("@mid",DemoDb.Id()),("@q",qty),("@u",UserId(u)),("@r",id),("@cost",cost),("@now",DemoDb.Now));}tx.Commit();return Results.Ok(new{id,status="confirmed"});});
        app.MapGet("/api/inventory/recipes/{kind}/{id:guid}",async(string kind,Guid id,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(kind is not("product" or "topping"))return Results.BadRequest();await using var c=DemoDb.Open();var col=kind=="product"?"ProductId":"ToppingId";var rs=await DemoDb.Rows(c,$"SELECT r.IngredientId,i.Name Ingredient,i.Unit,r.Quantity,r.Quantity*i.AverageCost EstimatedCost FROM RecipeComponents r JOIN Ingredients i ON i.Id=r.IngredientId WHERE r.{col}=@id",("@id",id));return Results.Ok(rs.Select(r=>new{ingredientId=r.G("IngredientId"),ingredient=r.S("Ingredient"),unit=r.S("Unit"),quantity=Convert.ToDecimal(r["Quantity"]),estimatedCost=Convert.ToDecimal(r["EstimatedCost"])}));});
        app.MapPut("/api/inventory/recipes/{kind}/{id:guid}",async(string kind,Guid id,RecipeDemoInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(kind is not("product" or "topping")||x.Items.Any(i=>i.Quantity<=0))return Results.BadRequest(new{error="Công thức không hợp lệ."});await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var col=kind=="product"?"ProductId":"ToppingId";await DemoDb.Exec(c,tx,$"DELETE FROM RecipeComponents WHERE {col}=@id",("@id",id));foreach(var i in x.Items)await DemoDb.Exec(c,tx,$"INSERT INTO RecipeComponents(Id,{col},IngredientId,Quantity)VALUES(@id,@owner,@ingredient,@q)",( "@id",DemoDb.Id()),("@owner",id),("@ingredient",i.IngredientId),("@q",i.Quantity));tx.Commit();return Results.Ok(new{id,kind,count=x.Items.Count});});
        app.MapPost("/api/inventory/adjustments",async(AdjustmentDemoInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.QuantityChange==0||string.IsNullOrWhiteSpace(x.Reason))return Results.BadRequest(new{error="Nhập số lượng và lý do."});await using var c=DemoDb.Open();using var tx=c.BeginTransaction();await DemoDb.Exec(c,tx,"UPDATE Ingredients SET Quantity=Quantity+@q WHERE Id=@id",("@q",x.QuantityChange),("@id",x.IngredientId));var balance=await ScalarDecimal(c,tx,"SELECT Quantity FROM Ingredients WHERE Id=@id",("@id",x.IngredientId));await DemoDb.Exec(c,tx,"INSERT INTO StockMovements(Id,IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,BalanceAfter,CreatedAt)VALUES(@mid,@id,@q,@reason,@u,@type,'manual',@ref,@b,@now)",( "@mid",DemoDb.Id()),("@id",x.IngredientId),("@q",x.QuantityChange),("@reason",x.Reason.Trim()),("@u",UserId(u)),("@type",x.QuantityChange<0?"waste":"adjustment"),("@ref",DemoDb.Id()),("@b",balance),("@now",DemoDb.Now));tx.Commit();return Results.Ok(new{x.IngredientId,x.QuantityChange});});
        app.MapPost("/api/inventory/counts",async(CountDemoInput x,ClaimsPrincipal u)=>{if(!Manager(u))return Denied();if(x.Items.Count==0)return Results.BadRequest(new{error="Phiếu kiểm kê trống."});await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var id=DemoDb.Id();var no=await ScalarLong(c,tx,"SELECT COALESCE(MAX(CountNumber),999)+1 FROM InventoryCounts");await DemoDb.Exec(c,tx,"INSERT INTO InventoryCounts(Id,StoreId,CountNumber,Note,CreatedBy,CreatedAt)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@no,@note,@u,@now)",( "@id",id),("@no",no),("@note",x.Note),("@u",UserId(u)),("@now",DemoDb.Now));foreach(var i in x.Items){var system=await ScalarDecimal(c,tx,"SELECT Quantity FROM Ingredients WHERE Id=@id",("@id",i.IngredientId));var diff=i.ActualQuantity-system;await DemoDb.Exec(c,tx,"INSERT INTO InventoryCountItems(Id,CountId,IngredientId,SystemQuantity,ActualQuantity,Difference)VALUES(@x,@c,@i,@s,@a,@d);UPDATE Ingredients SET Quantity=@a WHERE Id=@i;INSERT INTO StockMovements(Id,IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,BalanceAfter,CreatedAt)VALUES(@m,@i,@d,'Chênh lệch kiểm kê',@u,'count','inventory_count',@c,@a,@now)",( "@x",DemoDb.Id()),("@c",id),("@i",i.IngredientId),("@s",system),("@a",i.ActualQuantity),("@d",diff),("@m",DemoDb.Id()),("@u",UserId(u)),("@now",DemoDb.Now));}tx.Commit();return Results.Ok(new{id=Guid.Parse(id),countNumber=no});});
        app.MapGet("/api/inventory/report",async(ClaimsPrincipal u)=>{if(!Manager(u))return Denied();await using var c=DemoDb.Open();var s=(await DemoDb.Rows(c,"SELECT COUNT(*) IngredientCount,SUM(CASE WHEN Quantity<=ReorderLevel THEN 1 ELSE 0 END) LowStockCount,COALESCE(SUM(Quantity*AverageCost),0) StockValue FROM Ingredients WHERE IsActive=1")).First();var rows=await DemoDb.Rows(c,"SELECT m.*,i.Name Ingredient,i.Unit,COALESCE(u.FullName,'Hệ thống') Staff FROM StockMovements m JOIN Ingredients i ON i.Id=m.IngredientId LEFT JOIN Users u ON u.Id=m.CreatedBy ORDER BY m.CreatedAt DESC LIMIT 100");var costs=(await DemoDb.Rows(c,"SELECT COALESCE(SUM(CASE WHEN MovementType='waste' THEN ABS(QuantityChange)*COALESCE(UnitCost,i.AverageCost) ELSE 0 END),0) WasteCost,COALESCE(SUM(CASE WHEN MovementType='consumption' THEN ABS(QuantityChange)*COALESCE(UnitCost,i.AverageCost) ELSE 0 END),0) ConsumptionCost FROM StockMovements m JOIN Ingredients i ON i.Id=m.IngredientId")).First();return Results.Ok(new{summary=new{ingredientCount=s.I("IngredientCount"),lowStockCount=s.I("LowStockCount"),stockValue=Convert.ToDecimal(s["StockValue"])},movements=rows.Select(r=>new{id=r.G("Id"),ingredient=r.S("Ingredient"),unit=r.S("Unit"),quantityChange=Convert.ToDecimal(r["QuantityChange"]),type=r.S("MovementType"),reason=r.S("Reason"),balanceAfter=r["BalanceAfter"] is null?(decimal?)null:Convert.ToDecimal(r["BalanceAfter"]),createdAt=r.D("CreatedAt"),staff=r.S("Staff")}),costs=new{wasteCost=Convert.ToDecimal(costs["WasteCost"]),consumptionCost=Convert.ToDecimal(costs["ConsumptionCost"])}});});
    }

    public static async Task DeductItem(SqliteConnection c,SqliteTransaction tx,string itemId,string userId)
    {
        if(await DemoDb.Exec(c,tx,"UPDATE OrderItems SET InventoryDeducted=1,InventoryDeductedAt=@now WHERE Id=@id AND InventoryDeducted=0 AND Status<>'cancelled'",("@now",DemoDb.Now),("@id",itemId))==0)return;
        var required=await DemoDb.Rows(c,tx,"SELECT IngredientId,SUM(Qty) Qty FROM (SELECT r.IngredientId,r.Quantity*i.Quantity Qty FROM OrderItems i JOIN RecipeComponents r ON r.ProductId=i.ProductId WHERE i.Id=@id UNION ALL SELECT r.IngredientId,r.Quantity*i.Quantity*t.Quantity Qty FROM OrderItems i JOIN OrderItemToppings t ON t.OrderItemId=i.Id JOIN RecipeComponents r ON r.ToppingId=t.ToppingId WHERE i.Id=@id) GROUP BY IngredientId",("@id",itemId));
        foreach(var r in required){var qty=Convert.ToDecimal(r["Qty"]);await DemoDb.Exec(c,tx,"UPDATE Ingredients SET Quantity=Quantity-@q WHERE Id=@i",("@q",qty),("@i",r.S("IngredientId")));var ing=(await DemoDb.Rows(c,tx,"SELECT Quantity,AverageCost FROM Ingredients WHERE Id=@i",("@i",r.S("IngredientId")))).First();await DemoDb.Exec(c,tx,"INSERT INTO StockMovements(Id,IngredientId,QuantityChange,Reason,CreatedBy,MovementType,ReferenceType,ReferenceId,UnitCost,BalanceAfter,CreatedAt)VALUES(@m,@i,@q,'Trừ theo định lượng khi bắt đầu pha',@u,'consumption','order_item',@ref,@cost,@b,@now)",( "@m",DemoDb.Id()),("@i",r.S("IngredientId")),("@q",-qty),("@u",userId),("@ref",itemId),("@cost",ing["AverageCost"]),("@b",ing["Quantity"]),("@now",DemoDb.Now));}
    }
    public static async Task DeductOrder(SqliteConnection c,SqliteTransaction tx,string orderId,string userId){var ids=await DemoDb.Rows(c,tx,"SELECT Id FROM OrderItems WHERE OrderId=@o AND Status<>'cancelled'",("@o",orderId));foreach(var i in ids)await DeductItem(c,tx,i.S("Id"),userId);}
    public static Task MarkWaste(SqliteConnection c,SqliteTransaction tx,string orderId)=>DemoDb.Exec(c,tx,"UPDATE StockMovements SET MovementType='waste',Reason='Hao hụt do hủy đơn sau khi pha' WHERE ReferenceType='order_item' AND MovementType='consumption' AND ReferenceId IN (SELECT Id FROM OrderItems WHERE OrderId=@o)",("@o",orderId));
    static async Task<long> ScalarLong(SqliteConnection c,SqliteTransaction tx,string sql,params(string,object?)[] args)=>Convert.ToInt64(await DemoDb.Command(c,sql,tx,args).ExecuteScalarAsync()??0);
    static async Task<decimal> ScalarDecimal(SqliteConnection c,SqliteTransaction tx,string sql,params(string,object?)[] args)=>Convert.ToDecimal(await DemoDb.Command(c,sql,tx,args).ExecuteScalarAsync()??0);
}

record IngredientDemoInput(string Name,string Unit,decimal ReorderLevel,string? Code,string? Category);
record SupplierDemoInput(string Name,string? Phone,string? Address,string? Note);
record ReceiptDemoInput(Guid? SupplierId,string? Note,List<ReceiptItemDemoInput> Items);
record ReceiptItemDemoInput(Guid IngredientId,decimal Quantity,decimal UnitCost);
record RecipeDemoInput(List<RecipeItemDemoInput> Items);
record RecipeItemDemoInput(Guid IngredientId,decimal Quantity);
record AdjustmentDemoInput(Guid IngredientId,decimal QuantityChange,string Reason);
record CountDemoInput(string? Note,List<CountItemDemoInput> Items);
record CountItemDemoInput(Guid IngredientId,decimal ActualQuantity);
